import { Plugin } from "@opencode/plugin";
import { identityAccessorFrom, studioUrlFrom } from "./domain/config.js";
import { registerApprovalRules } from "./host/agents.js";
import { registerIntegrations } from "./host/integrations.js";
import { registerSkill } from "./host/skills.js";
import { registerTools } from "./host/tools.js";
/**
 * toqan artifacts: Studio's tools, skill and default permissions in one
 * install. Setup does local work only — read the options, tools.json and the
 * skill, then register — and never calls Studio. The first network call is the
 * person's sign-in through /connect.
 */
export default Plugin.define({
    id: "jelly-artifacts",
    async setup(ctx) {
        const studioUrl = studioUrlFrom(ctx.options);
        const identityAccessor = identityAccessorFrom(ctx.options);
        await registerIntegrations(ctx, studioUrl);
        await registerApprovalRules(ctx);
        await registerTools(ctx, studioUrl, identityAccessor);
        await registerSkill(ctx);
    },
});
